import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-cruz', 'B',
 [dict(t=2202, e=2250, titulo='El poder del mensaje de la cruz', txt='El poder, diga conmigo, el poder del mensaje de la cruz. ¿Qué le quiero decir con eso? Que la cruz tiene un poder por lo que pasó en ella. Y ahí empieza el mensaje más maravilloso para su vida, un mensaje de amor, porque por amor murió Jesucristo por usted y por mí. Pero lo increíble es que Dios el Padre mostró su amor a nosotros dando a su Hijo unigénito: se despojó de lo que más amaba.'),
  dict(t=2516, e=2562, titulo='Abrir la boca por otros', txt='Va a cambiar el poder del mensaje de la cruz. Primera de Corintios 1:17: «Pues Cristo no me envió a bautizar, sino a predicar el evangelio». Este es el tiempo de predicar. Este es el tiempo de que yo le voy a hablar a mi abuelita, le voy a hablar a mi hermano, le voy a hablar a mi primo. No me importa que me digan que estoy loco: yo le predico, porque de repente viene la revelación, les abre los ojos y se salvan. Creo que tenemos una responsabilidad de abrir la boca y de invocar al Señor por otros.'),
  dict(t=4011, e=4052, titulo='Clavado en la cruz', txt='[…] que consistía en decretos contra nosotros, que nos eran adversos, y lo ha quitado de en medio, clavándolo en la cruz; y habiendo despojado a los poderes y autoridades, hizo de ellos un espectáculo público, triunfando sobre ellos por medio de él. ¿Sí me está entendiendo, iglesia? La cruz: motivo de consagración y transformación.')],
 [dict(t=1370, txt='Sin esto no hubiera habido nada, porque ¿a dónde hubieran puesto al Señor Jesucristo?'),
  dict(t=2793, txt='Para nosotros los salvos, la palabra de la cruz es poder de Dios.'),
  dict(t=4413, txt='Es hora de que empieces a ver lo espiritual.')],
 ['Si la cruz es un mensaje de amor, ¿qué te dice hoy que el Padre se «despojó de lo que más amaba» por ti?',
  '¿A qué familiar o amigo te ha puesto el Señor en el corazón para hablarle de la cruz esta semana, aunque te digan que estás loco?',
  'Si los decretos contra ti fueron clavados en la cruz, ¿qué acusación o culpa sigues cargando que ya fue quitada de en medio?'])
